CREATE OR REPLACE FUNCTION private.org_role_permission_ready(p text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT p=ANY(ARRAY['leave.create','leave.view_own','leave.edit_own','leave.recall','att.create','att.view_own','att.edit_own','att.witness','order.view','order.view_mine','order.update_draft','order.submit','order.resubmit','order.deliver','order.history','order.open_delivery','ot.view_own','ot.task_view','ot.task_update','ot.stage_update','order.create','order.take','oq.create','oq.accept','oq.reply_price','oq.reply_progress','oq.report_own']) $$;
CREATE OR REPLACE FUNCTION private.org_role_audit_reason(p text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN private.org_role_permission_ready(p) THEN 'native_personal_verified' WHEN p LIKE 'biz.%' OR p LIKE 'k3.%' THEN 'appointment_only' WHEN p LIKE 'finance.%' THEN 'finance_unit_scope_missing' WHEN p LIKE 'leave.%' OR p LIKE 'att.%' THEN 'hr_unit_scope_missing' WHEN p LIKE 'oq.%' OR p LIKE 'ot.%' THEN 'order_unit_scope_missing' WHEN p LIKE 'settings.%' THEN 'global_configuration' ELSE 'backend_scope_workflow_missing' END $$;
DO $$ DECLARE d text;BEGIN
 SELECT pg_get_functiondef('public.base_title_roles_read()'::regprocedure) INTO d;
 IF d NOT LIKE '%scope_audit_pending%' THEN RAISE EXCEPTION 'Unexpected title read contract';END IF;
 d:=replace(d,$s$CASE WHEN private.org_role_permission_ready(p) THEN 'native_personal_verified' WHEN p LIKE 'biz.%' OR p LIKE 'k3.%' THEN 'appointment_only' ELSE 'scope_audit_pending' END$s$,'private.org_role_audit_reason(p)'); EXECUTE d;
 SELECT pg_get_functiondef('private.org_commands(jsonb)'::regprocedure) INTO d;
 IF d NOT LIKE '%at_:=coalesce(nullif(v->>''starts_at''%' OR d NOT LIKE '%Mốc kết thúc không hợp lệ%' THEN RAISE EXCEPTION 'Unexpected assignment contract'; END IF;
 d:=replace(d,$s$at_:=coalesce(nullif(v->>'starts_at','')::timestamptz,clock_timestamp());$s$,$s$IF title_.source IS DISTINCT FROM 'biz_positions' AND v->>'user_id'=auth.uid()::text AND NOT private.is_super_admin(auth.uid()) AND EXISTS(SELECT 1 FROM base_title_role_links l WHERE l.title_source='base' AND l.title_id=title_.id AND cardinality(l.enabled_permissions)>0) THEN RAISE EXCEPTION 'Không tự phân công vào chức vụ có quyền tự cấp; cần quản trị khác xác nhận.';END IF;
 at_:=coalesce(nullif(v->>'starts_at','')::timestamptz,clock_timestamp());$s$);
 d:=replace(d,$s$RAISE EXCEPTION 'Mốc kết thúc không hợp lệ.';END IF;END IF;$s$,$s$RAISE EXCEPTION 'Mốc kết thúc không hợp lệ.';END IF;
 IF old_.source NOT LIKE 'biz_%' AND old_.ends_at IS NOT NULL AND at_>old_.ends_at THEN RAISE EXCEPTION 'Không gia hạn phân công bằng thao tác kết thúc.';END IF;END IF;$s$); EXECUTE d;
END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.base_title_roles_read()'::regprocedure) INTO d;EXECUTE replace(d,'FUNCTION public.base_title_roles_read(','FUNCTION private.phase3a_title_roles_read(');END $$;
CREATE OR REPLACE FUNCTION public.base_title_roles_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result_ jsonb;BEGIN
 result_:=private.phase3a_title_roles_read();
 RETURN result_||jsonb_build_object('link_audits',(SELECT coalesce(jsonb_agg(jsonb_build_object('title_id',t.id,'title_name',t.name,'role_id',r.id,'role_name',r.name,'scope_kind',l.scope_kind,'signature_valid',l.permission_signature=md5(coalesce(r.permissions,'{}')::text),'enabled',(SELECT coalesce(jsonb_agg(p ORDER BY p),'[]') FROM unnest(l.enabled_permissions) p WHERE private.org_role_permission_ready(p) AND p=ANY(r.permissions) AND l.scope_kind='own' AND l.permission_signature=md5(coalesce(r.permissions,'{}')::text)),'eligible',(SELECT coalesce(jsonb_agg(p ORDER BY p),'[]') FROM unnest(r.permissions)p WHERE private.org_role_permission_ready(p)),'blocked',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',p,'reason',private.org_role_audit_reason(p)) ORDER BY p),'[]') FROM unnest(r.permissions)p WHERE NOT private.org_role_permission_ready(p))) ORDER BY t.name),'[]') FROM base_title_role_links l JOIN org_titles t ON t.id=l.title_id JOIN app_roles r ON r.id=l.role_id WHERE l.title_source='base' AND t.source IS DISTINCT FROM 'biz_positions'));
END $$;
REVOKE ALL ON FUNCTION private.phase3a_title_roles_read(),private.org_role_audit_reason(text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.base_title_roles_read() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.base_title_roles_read() TO authenticated,service_role;